// start
void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 4096 + (int)(conflicts * 0.001);
    // Occasionally flip the saved phases to escape local optima
    int mode = (int)(conflicts / 10000) % 4;
    if (mode == 0) {
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if (mode == 1) {
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if (mode == 2) {
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else {
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    }
}
// end
